import { initKeySync } from './key-sync.js';
const $=id=>document.getElementById(id);
let previous='記録なし';try{previous=localStorage.getItem('wm-audio-diagnostics')||previous;}catch{}$('previous').textContent=previous;
let logs=[],transcripts=[],run=null,epoch=0,recordUrl;
function log(message){logs.push(new Date().toISOString()+' '+message);logs=logs.slice(-350);$('logs').textContent=logs.join('\n');$('logs').scrollTop=$('logs').scrollHeight;try{localStorage.setItem('wm-audio-diagnostics',logs.join('\n'));}catch{}}
function safeError(e){let s=e?.message||String(e);const k=$('key').value.trim();if(k)s=s.split(k).join('[REDACTED]');return s.replace(/AIza[\w-]+/g,'[REDACTED]').slice(0,250);}
function status(s){$('state').textContent=s;}
function wav(bytes,rate){const b=new ArrayBuffer(44+bytes.length),d=new DataView(b);const str=(o,s)=>[...s].forEach((c,i)=>d.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');d.setUint32(4,36+bytes.length,true);str(8,'WAVE');str(12,'fmt ');d.setUint32(16,16,true);d.setUint16(20,1,true);d.setUint16(22,1,true);d.setUint32(24,rate,true);d.setUint32(28,rate*2,true);d.setUint16(32,2,true);d.setUint16(34,16,true);str(36,'data');d.setUint32(40,bytes.length,true);new Uint8Array(b,44).set(bytes);return new Blob([b],{type:'audio/wav'});}
const tone=new Uint8Array(16000*30*2),td=new DataView(tone.buffer);for(let i=0;i<tone.length/2;i++){const f=330+Math.floor(i/16000/5)*110;td.setInt16(i*2,Math.sin(2*Math.PI*f*i/16000)*2200,true);}$('tone').src=URL.createObjectURL(wav(tone,16000));
for(const event of ['play','pause','ended','waiting','error'])$('tone').addEventListener(event,()=>log('テスト音 '+event));
const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
$('env').textContent=(standalone?'ホーム画面版':'ブラウザ版')+' / '+(isSecureContext?'HTTPS対応':'HTTPSが必要');log(navigator.userAgent);log('起動 '+$('env').textContent);
document.querySelectorAll('[name=mode]').forEach(el=>el.onchange=()=>{$('liveOptions').hidden=document.querySelector('[name=mode]:checked').value!=='live';status('準備完了');});
function render(){const r=run;if(!r){$('metrics').textContent='未接続';return;}const track=r.stream?.getAudioTracks()[0];$('metrics').textContent=`経過 ${Math.round((Date.now()-r.started)/1000)}秒 / マイク ${track?.readyState||'準備中'}${track?.muted?' (muted)':''}\nAudioContext ${r.ctx?.state||'なし'} / 入力 ${r.frames}チャンク / 無音以外 ${r.active}\n送信 ${(r.sent/1024).toFixed(0)}KB / 受信音声 ${r.received}チャンク / WS ${r.ws?['接続中','OPEN','終了中','CLOSED'][r.ws.readyState]:'なし'}`;}
function expired(r){if(run!==r)return true;if(Date.now()-r.started>=180000){void stop('3分の上限で停止');return true;}return false;}
function clearPlayback(r){for(const s of r.sources){try{s.stop();}catch{}}r.sources.clear();r.next=0;}
async function stop(reason='手動停止'){
 const stopEpoch=++epoch;const r=run;run=null;if(r){clearInterval(r.timer);clearTimeout(r.limit);clearTimeout(r.setupTimer);r.ws?.close(1000,'stopped');clearPlayback(r);r.processor?.disconnect();r.source?.disconnect();r.gain?.disconnect();r.stream?.getTracks().forEach(t=>t.stop());await r.ctx?.close().catch(()=>{});if(stopEpoch!==epoch)return;if(r.parts.length){if(recordUrl)URL.revokeObjectURL(recordUrl);const count=r.parts.reduce((a,b)=>a+b.length,0),bytes=new Uint8Array(count);let o=0;for(const p of r.parts){bytes.set(p,o);o+=p.length;}recordUrl=URL.createObjectURL(wav(bytes,r.rate));$('recording').src=recordUrl;$('recording').hidden=false;$('recordNote').textContent=`実際に採取できた音声 ${(count/2/r.rate).toFixed(1)}秒 ／ 実経過 ${((Date.now()-r.started)/1000).toFixed(1)}秒。ロック中の発言があるか再生して確認。`; }log(`${reason} / 入力 ${r.frames} / 発話あり ${r.active} / 送信 ${r.sent} bytes / 受信 ${r.received}`);}
 if(stopEpoch!==epoch)return;
 $('start').disabled=false;$('stop').disabled=true;document.querySelectorAll('[name=mode],#sessionType,#model').forEach(e=>e.disabled=false);status(reason);$('level').value=0;render();
}
function playPCM(r,data,mime){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0)),view=new DataView(bytes.buffer),rate=Number(/rate=(\d+)/.exec(mime||'')?.[1]||24000);const b=r.ctx.createBuffer(1,Math.floor(bytes.length/2),rate),f=b.getChannelData(0);for(let i=0;i<f.length;i++)f[i]=view.getInt16(i*2,true)/32768;const src=r.ctx.createBufferSource();src.buffer=b;src.connect(r.ctx.destination);r.next=Math.max(r.next||0,r.ctx.currentTime+.02);src.start(r.next);r.next+=b.duration;r.sources.add(src);src.onended=()=>r.sources.delete(src);r.received++;if(r.received===1||r.received%40===0)log('Live音声受信 '+r.received+' / AudioContext '+r.ctx.state);}
async function start(){if(run)return;const live=document.querySelector('[name=mode]:checked').value==='live',key=$('key').value.trim();if(live&&!key){status('APIキーを入力してください');return;}const id=++epoch;const r=run={started:Date.now(),frames:0,active:0,sent:0,received:0,parts:[],sources:new Set(),next:0,ready:false};$('start').disabled=true;$('stop').disabled=false;document.querySelectorAll('[name=mode],#sessionType,#model').forEach(e=>e.disabled=true);$('recording').hidden=true;$('recordNote').textContent='';status('マイクを準備中');
 try{
 if(!isSecureContext||!navigator.mediaDevices?.getUserMedia)throw Error('HTTPSとマイク対応ブラウザが必要です');
 if($('sessionType').checked&&navigator.audioSession){navigator.audioSession.type='play-and-record';log('audioSession.type = play-and-record');}
 r.ctx=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000});await r.ctx.resume();if(id!==epoch)return;if(expired(r))return;
 const stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(id!==epoch){stream.getTracks().forEach(t=>t.stop());return;}r.stream=stream;if(expired(r))return;r.rate=r.ctx.sampleRate;
 const track=stream.getAudioTracks()[0];for(const event of ['mute','unmute','ended'])track.addEventListener(event,()=>{if(run===r)log('マイク '+event);});r.ctx.onstatechange=()=>{if(run===r)log('AudioContext '+r.ctx.state);};
 r.source=r.ctx.createMediaStreamSource(stream);r.processor=r.ctx.createScriptProcessor(2048,1,1);r.gain=r.ctx.createGain();r.gain.gain.value=0;r.source.connect(r.processor);r.processor.connect(r.gain);r.gain.connect(r.ctx.destination);
 r.processor.onaudioprocess=e=>{if(expired(r))return;const f=e.inputBuffer.getChannelData(0);let sum=0;for(const v of f)sum+=v*v;const rms=Math.sqrt(sum/f.length);$('level').value=Math.min(1,rms*8);r.frames++;if(rms>.01)r.active++;const ratio=r.rate/16000,n=Math.floor(f.length/ratio),pcm=new Uint8Array(n*2),dv=new DataView(pcm.buffer);for(let i=0;i<n;i++){const p=i*ratio,j=Math.floor(p),v=Math.max(-1,Math.min(1,f[j]+((f[Math.min(j+1,f.length-1)]-f[j])*(p-j))));dv.setInt16(i*2,v<0?v*32768:v*32767,true);}if(live){if(r.ready&&r.ws?.readyState===1){if(r.ws.bufferedAmount>1024*256){log('送信詰まり: 停止');void stop('送信詰まり');return;}r.ws.send(JSON.stringify({realtimeInput:{audio:{mimeType:'audio/pcm;rate=16000',data:btoa(String.fromCharCode(...pcm))}}}));r.sent+=pcm.length;}}else{const raw=new Uint8Array(f.length*2),d=new DataView(raw.buffer);for(let i=0;i<f.length;i++)d.setInt16(i*2,Math.max(-1,Math.min(1,f[i]))*32767,true);r.parts.push(raw);}};
 let last=Date.now();r.timer=setInterval(()=>{if(expired(r))return;const now=Date.now();if(now-last>3500)log('タイマー停止/遅延 '+((now-last)/1000).toFixed(1)+'秒');last=now;render();},1000);r.limit=setTimeout(()=>void stop('3分の上限で停止'),180000);
 log(`開始 ${live?'Gemini Live':'ローカル録音'} / sampleRate ${r.rate}`);
 if(!live){status('録音中 — 画面をロックして話してください');return;}
 status('Gemini Liveへ接続中');const ws=r.ws=new WebSocket('wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContent?key='+encodeURIComponent(key));
 r.setupTimer=setTimeout(()=>{if(run===r&&!r.ready)void stop('Live接続タイムアウト');},20000);
 ws.onopen=()=>{if(expired(r))return;log('WebSocket OPEN');ws.send(JSON.stringify({setup:{model:'models/'+$('model').value.trim().replace(/^models\//,''),generationConfig:{responseModalities:['AUDIO'],speechConfig:{voiceConfig:{prebuiltVoiceConfig:{voiceName:'Puck'}}}},systemInstruction:{parts:[{text:'You are an English learning audio test assistant. Translate each Japanese utterance into one short natural English sentence. If the user speaks English, briefly improve it. No greetings or questions. On hearing a test phrase, respond so the user can verify background audio.'}]},inputAudioTranscription:{},outputAudioTranscription:{}}}));};
 ws.onmessage=async e=>{try{const text=typeof e.data==='string'?e.data:await e.data.text();if(expired(r))return;const m=JSON.parse(text);if(m.error){log('Liveエラー '+safeError(m.error));await stop('Liveエラー');return;}if(m.setupComplete){clearTimeout(r.setupTimer);r.ready=true;status('Live接続中 — ロックして話してください');log('Live setupComplete');}const s=m.serverContent;if(s){if(s.interrupted){clearPlayback(r);log('AI発話が割り込まれました');}for(const p of s.modelTurn?.parts||[])if(p.inlineData?.data)playPCM(r,p.inlineData.data,p.inlineData.mimeType);for(const [key,label] of [['inputTranscription','自分'],['outputTranscription','AI']])if(s[key]?.text){const line=new Date().toISOString()+' '+label+': '+s[key].text;transcripts.push(line);transcripts=transcripts.slice(-300);$('transcript').textContent=transcripts.join('\n');log(label+'の認識テキスト受信');}if(s.turnComplete)log('AIターン完了');}if(m.goAway)log('サーバーから終了予告（自動再接続なし）');}catch(e){log('受信処理エラー '+safeError(e));}};
 ws.onerror=()=>{if(run===r)log('WebSocketエラー（キー・モデル・利用枠を確認）');};ws.onclose=e=>{if(run===r){log('WebSocket CLOSE '+e.code+' '+safeError(e.reason));void stop('Live接続が終了');}};
 }catch(e){if(id!==epoch)return;log('開始エラー '+safeError(e));await stop('開始失敗: '+safeError(e));}
}
$('start').onclick=()=>void start();$('stop').onclick=()=>void stop();$('resume').onclick=async()=>{log('利用者が音声再開を操作');try{await run?.ctx?.resume();log('音声再開結果 '+(run?.ctx?.state||'未接続'));}catch(e){log(safeError(e));}};
document.addEventListener('visibilitychange',()=>{log('visibility '+document.visibilityState);if(run)expired(run);render();});for(const event of ['pagehide','pageshow','online','offline'])window.addEventListener(event,e=>{log(event+(e.persisted?' bfcache':''));if(run)expired(run);});
$('export').onclick=()=>{const b=new Blob([JSON.stringify({version:1,userAgent:navigator.userAgent,standalone,logs,transcripts},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='wearablemutter-audio-test.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};render();
initKeySync({getKey:()=>$('key').value,setKey:value=>{$('key').value=value;},beforeAccountChange:async()=>{if(run)await stop('Googleアカウント変更のため停止');}});
